return $input.all().map(item => {
  try {
    const respuesta = item.json.output ?? item.json['producción'];
    const datos = typeof respuesta === 'string'
      ? JSON.parse(respuesta.replace(/^```(?:json)?\s*|\s*```$/g, '').trim())
      : respuesta;

    if (!datos || typeof datos !== 'object' || Array.isArray(datos)) {
      throw new Error('Respuesta sin objeto JSON válido');
    }

    return {
      json: {
        localidad: datos.localidad ?? null,
        milimetros: datos.milimetros ?? null,
        tipo_registro: datos.tipo_registro ?? 'AMBIGUO',
        requiere_revision: datos.requiere_revision !== false,
        estado: 'PENDIENTE_VALIDACION'
      }
    };
  } catch (error) {
    return {
      json: {
        estado: 'ERROR_INTERPRETACION',
        requiere_revision: true,
        detalle_error: error.message
      }
    };
  }
});

const interpretacion = $('Code in JavaScript').first().json;
const mensaje = $('Edit Fields').first().json.mensaje || '';

const puntos = $input.all()
  .map(item => item.json)
  .filter(punto => punto.id_punto);

if (puntos.length !== 1 || puntos[0].activo !== 'SI') {
  return [{
    json: {
      localidad: interpretacion.localidad ?? null,
      id_punto: null,
      milimetros: interpretacion.milimetros ?? null,
      tipo_registro: interpretacion.tipo_registro,
      requiere_revision: true,
      estado: 'PENDIENTE_IDENTIFICACION',
      motivo: puntos.length === 0
        ? 'Informante no encontrado'
        : 'Informante duplicado o inactivo'
    }
  }];
}

const punto = puntos[0];

const fecha_mensaje = $('Edit Fields').first().json.fecha_mensaje || null;
return [{
  json: {
    id_punto: punto.id_punto,
    localidad: punto.localidad,
    telefono: punto.telefono ?? null,
fecha_mensaje: fecha_mensaje,
mensaje_original: mensaje,
    milimetros: interpretacion.milimetros ?? null,
    tipo_registro: interpretacion.tipo_registro,
    requiere_revision: true,
    estado: 'PENDIENTE_VALIDACION',
    activo: punto.activo,
    tipo_fuente: punto.tipo_fuente
  }
}];

const items = $input.all();

return items.map(item => {
  const mensaje = item.json.mensaje || "";

  // Separar fecha, remitente y contenido del mensaje
  const patron = /^\[([^\]]+)\]\s+(.+?):\s+([\s\S]*)$/;
  const resultado = mensaje.match(patron);

  if (!resultado) {
    return {
      json: {
        mensaje_original: mensaje,
        estado: "PENDIENTE_REVISION",
        motivo: "No se pudo identificar el formato del mensaje"
      }
    };
  }

  const fecha = resultado[1];
  const remitente = resultado[2].trim();
  const texto = resultado[3].trim();

  // Detectar si el remitente es un número de teléfono
  const telefono = /^\+?[\d\s()-]{8,}$/.test(remitente)
    ? remitente.replace(/[^\d+]/g, "")
    : null;

  return {
    json: {
      fecha_mensaje: fecha,
      remitente: remitente,
      telefono: telefono,
      nombre_whatsapp: telefono ? null : remitente,
      texto_mensaje: texto,
      estado: "PENDIENTE_IDENTIFICACION"
    }
  };
});

const eventos = $input.all().map(item => item.json);

if (eventos.length !== 1 || !eventos[0].id_evento) {
  throw new Error(
    'Debe existir exactamente un evento abierto con identificador.'
  );
}

const evento = eventos[0];

return [{
  json: {
    id_evento: evento.id_evento,
    fecha_inicio: evento.fecha_inicio,
    fecha_fin: evento.fecha_fin,
    estado: evento.estado
  }
}];

const registro = $('Code in JavaScript1').first().json;
const evento = $('Code in JavaScript3').first().json;

if (!registro.id_punto || registro.milimetros == null) {
  throw new Error('Faltan datos del registro de precipitaciones');
}

if (!evento.id_evento || evento.estado !== 'ABIERTO') {
  throw new Error('No se encontró un evento abierto válido');
}

// Generar identificador estable del mensaje
const textoIdentificador = [
  evento.id_evento,
  registro.id_punto,
  registro.fecha_mensaje,
  registro.mensaje_original
].map(valor => String(valor ?? '')).join('|');

if (!registro.fecha_mensaje || !registro.mensaje_original) {
  throw new Error('Faltan datos para identificar el mensaje');
}

// Hash sencillo y determinístico
let hash = 2166136261;
for (let i = 0; i < textoIdentificador.length; i++) {
  hash ^= textoIdentificador.charCodeAt(i);
  hash = Math.imul(hash, 16777619);
}

const idMensaje = 'MSG-' + (hash >>> 0).toString(16).padStart(8, '0');

return [{
  json: {
    id_evento: evento.id_evento,
    id_punto: registro.id_punto,
    localidad: registro.localidad,
    milimetros: registro.milimetros,
    fecha_mensaje: registro.fecha_mensaje,
    fuente: registro.tipo_fuente,
    tipo_registro: registro.tipo_registro,
    mensaje_original: registro.mensaje_original,
    id_mensaje: idMensaje,
    validado: 'NO',
    estado: 'PENDIENTE_VALIDACION'
  }
}];

const nuevo = $('Code in JavaScript4').first().json;

// Registros encontrados en Google Sheets
const existentes = $input.all()
  .map(item => item.json)
  .filter(fila => fila.id_mensaje);

// Verificar si el mensaje ya fue registrado
const duplicado = existentes.some(
  fila => String(fila.id_mensaje) === String(nuevo.id_mensaje)
);

return [{
  json: {
    ...nuevo,
    duplicado: duplicado,
    accion: duplicado ? 'OMITIR' : 'GUARDAR'
  }
}];
